import torch
import numpy as np

# Let me redo the trigger testing more carefully
def create_trigger_patch(trigger_type='white', size=3):
    """Create just the trigger patch"""
    patch = torch.zeros(3, size, size, dtype=torch.uint8)
    if trigger_type == 'white':
        patch[:] = 255
    elif trigger_type == 'checkerboard':
        for i in range(size):
            for j in range(size):
                val = 255 if (i+j) % 2 == 0 else 0
                patch[:, i, j] = val
    elif trigger_type == 'random':
        noise = torch.randint(0, 2, (size, size)) * 255
        patch[:] = noise.unsqueeze(0)
    return patch

def apply_trigger(img, patch, corner='top_left'):
    """Apply trigger patch to image at specified corner (1 pixel in)"""
    img = img.clone()
    sz = patch.shape[1]
    if corner == 'top_left':
        img[:, 1:1+sz, 1:1+sz] = patch
    elif corner == 'top_right':
        img[:, 1:1+sz, 32-1-sz:32-1] = patch
    elif corner == 'bottom_left':
        img[:, 32-1-sz:32-1, 1:1+sz] = patch
    elif corner == 'bottom_right':
        img[:, 32-1-sz:32-1, 32-1-sz:32-1] = patch
    return img

